def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    from collections import defaultdict
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford algorithm
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax all edges n-1 times
    for i in range(n - 1):
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w

    # Check for negative weight cycles (not necessary if no negative weights, but included for completeness)
    for u in range(n):
        if dist[u] == float('inf'):
            continue
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                if v == t:
                    return -1  # Negative cycle allows reaching t with negative weight

    return dist[t] if dist[t] != float('inf') else -1
```

